import React, { useState, useEffect } from "react";
import "./chat.css";

function Chatbot() {
  const [text, setText] = useState("");
  const [chat, setChat] = useState([]); // conversation history
  const [recording, setRecording] = useState(false);
  const [mediaRecorder, setMediaRecorder] = useState(null);
  const [isTyping, setIsTyping] = useState(false);
  const [typingDots, setTypingDots] = useState("...");

  // ⏳ Animate "Assistant is thinking..."
  useEffect(() => {
    if (!isTyping) return;
    const interval = setInterval(() => {
      setTypingDots((prev) => (prev.length >= 3 ? "." : prev + "."));
    }, 500);
    return () => clearInterval(interval);
  }, [isTyping]);

  // 👉 Send text to backend
  const handleSend = async () => {
    if (!text.trim()) return;

    const userMsg = { sender: "user", text };
    setChat((prev) => [...prev, userMsg]);
    setText("");
    setIsTyping(true);

    try {
      const res = await fetch("/api/match", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text }),
      });
      const data = await res.json();

      const botMsg = {
        sender: "bot",
        text:
          data.message ||
          "Let me think... Based on your symptoms, here’s what I found:",
        input: data.input,
        symptoms: data.symptoms || [],
        predictions: data.predictions || [],
      };

      // Simulate 3–4s "thinking" delay
      const delay = 3000 + Math.random() * 1000;
      setTimeout(() => {
        setChat((prev) => [...prev, botMsg]);
        setIsTyping(false);
      }, delay);
    } catch (err) {
      console.error("Error:", err);
      setIsTyping(false);
    }
  };

  // 🎙️ Start voice recording
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = async () => {
        const blob = new Blob(chunks, { type: "audio/webm" });
        const formData = new FormData();
        formData.append("file", blob, "voice.webm");

        const userMsg = { sender: "user", text: "🎤 Voice message..." };
        setChat((prev) => [...prev, userMsg]);
        setIsTyping(true);

        const res = await fetch("/api/voice", {
          method: "POST",
          body: formData,
        });
        const data = await res.json();

        const botMsg = {
          sender: "bot",
          text:
            data.message ||
            "I’ve analyzed your voice input. Here’s what I found:",
          symptoms: data.symptoms || [],
          predictions: data.predictions || [],
        };

        // 3–4s delay for realism
        const delay = 3000 + Math.random() * 1000;
        setTimeout(() => {
          setChat((prev) => [...prev, botMsg]);
          setIsTyping(false);
        }, delay);
      };

      recorder.start();
      setMediaRecorder(recorder);
      setRecording(true);
    } catch (err) {
      console.error("Microphone error:", err);
      alert("Microphone not available or permission denied.");
    }
  };

  // ⏹️ Stop voice recording
  const stopRecording = () => {
    if (mediaRecorder) {
      mediaRecorder.stop();
      setRecording(false);
    }
  };

  return (
    <div
      style={{
        padding: "20px",
        maxWidth: "700px",
        margin: "0 auto",
        color: "#222",
      }}
    >
      <h2 style={{ textAlign: "center" }}>🩺 Smart Clinical Assistant</h2>

      {/* Chat Container */}
      <div
        style={{
          border: "1px solid #ccc",
          borderRadius: "12px",
          padding: "15px",
          height: "420px",
          overflowY: "auto",
          background: "#fafafa",
          marginBottom: "15px",
        }}
      >
        {chat.map((msg, idx) => (
          <div
            key={idx}
            style={{
              textAlign: msg.sender === "user" ? "right" : "left",
              marginBottom: "12px",
            }}
          >
            <div
              style={{
                display: "inline-block",
                background: msg.sender === "user" ? "#0084ff" : "#e5e5ea",
                color: msg.sender === "user" ? "#fff" : "#000",
                padding: "10px 14px",
                borderRadius: "16px",
                maxWidth: "80%",
                whiteSpace: "pre-line",
              }}
            >
              <div>{msg.text}</div>

              {/* Symptom + Prediction Section */}
              {msg.predictions?.length > 0 && (
                <div style={{ marginTop: "8px" }}>
                  {msg.symptoms?.length > 0 && (
                    <p>
                      <b>🧩 Detected Symptoms:</b> {msg.symptoms.join(", ")}
                    </p>
                  )}
                  <b>💊 Possible Diseases:</b>
                  <ul style={{ margin: "5px 0 0 15px" }}>
                    {msg.predictions.map((p, i) => (
                      <li key={i}>
                        {p.disease} ({p.score})
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}

        {isTyping && (
          <div style={{ textAlign: "left", marginTop: "10px" }}>
            <i>Assistant is thinking{typingDots}</i>
          </div>
        )}
      </div>

      {/* Input Section */}
      <div style={{ display: "flex", gap: "10px" }}>
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Describe your symptoms..."
          style={{
            flexGrow: 1,
            padding: "10px",
            borderRadius: "8px",
            border: "1px solid #ccc",
          }}
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button onClick={handleSend} style={{ padding: "10px 20px" }}>
          Send
        </button>
        <button
          onClick={recording ? stopRecording : startRecording}
          style={{
            padding: "10px 20px",
            background: recording ? "red" : "lightgreen",
            color: recording ? "#fff" : "#000",
            borderRadius: "6px",
          }}
        >
          {recording ? "Stop" : "🎤 Mic"}
        </button>
      </div>
    </div>
  );
}

export default Chatbot;
